"""Fail-closed quality gate for drafts generated by local Ollama.

This module never publishes. It must be applied BEFORE saving a draft_for_review.
A passing structural/heuristic check is not factual or editorial approval.
"""
import json

from scripts.presssport_caption_quality import LIMITS, REQUIRED, evaluate_draft


def apply_quality_gate(brief, raw_draft):
    """Return a safe five-field JSON draft and review issues.

    Any flagged channel is emptied so the review editor cannot accidentally
    accept an unsupported claim without writing a new caption. The original
    full raw draft is intentionally not echoed back in the accepted fields.
    """
    issues = evaluate_draft(brief, raw_draft)
    try:
        source = (raw_draft if isinstance(raw_draft, dict)
                  else json.loads(raw_draft))
        if not isinstance(source, dict):
            source = {}
    except (ValueError, TypeError):
        source = {}
    result = {}
    for key in REQUIRED:
        value = source.get(key)
        result[key] = value if isinstance(value, str) else ""

    if "invalid_json" in issues:
        for key in LIMITS:
            result[key] = ""

    for channel in LIMITS:
        if any(issue.endswith("_" + channel) or
               issue.startswith(channel + "_") or
               issue == "missing_" + channel
               for issue in issues):
            result[channel] = ""

    # The downstream UI already requires manual approval. Never indicate that
    # facts or permissions have been independently verified by Ollama.
    editorial_note = (
        "REVISIONE UMANA OBBLIGATORIA. Nessuna fonte esterna "
        "verificata automaticamente. Controllare fatti, autorizzazioni "
        "e diritti delle immagini."
    )
    if issues:
        editorial_note += (
            " QA NON SUPERATA: " + ", ".join(sorted(set(issues))) +
            ". NON PUBBLICARE."
        )
    old_notes = result["fact_checks"].strip()
    result["fact_checks"] = (
        old_notes + "\n" + editorial_note if old_notes else editorial_note
    )
    return {
        "draft": json.dumps(result, ensure_ascii=False),
        "issues": issues,
        "needs_human_review": True,
        "publish_allowed": False,
    }
